  "d.1qqfryw": "LOW EARTH ORBIT, de sektorôfbylding út it spielmenu. Opname út it spiel, ferzje 0.6.1",
  "d.1r805pn": "Ferzje 0.6.0 beferzen: in LOADOUT-skerm foar elke wedstriid, mei romp- en skyldnivo's en skyldkleur.",
  "d.1reld25": "FLAGGESKIP",
